INSERT INTO authors (author_id, first_name, last_name, biography) VALUES
(1, 'Jane', 'Austen', 'An English novelist known primarily for her six major novels, which interpret, critique and comment upon the British landed gentry at the end of the 18th century.'),
(2, 'George', 'Orwell', 'An English novelist, essayist, journalist, and critic whose work is marked by lucid prose, awareness of social injustice, opposition to totalitarianism, and outspoken support of democratic socialism.'),
(3, 'William', 'Shakespeare', 'An English playwright, poet and actor, widely regarded as the greatest writer in the English language and the world\'s greatest dramatist.'),
(4, 'Agatha', 'Christie', 'An English writer known for her sixty-six detective novels and fourteen short story collections, particularly those revolving around Hercule Poirot and Miss Marple.'),
(5, 'Ernest', 'Hemingway', 'An American novelist, short-story writer, journalist, and sportsman. His economical and understated style had a strong influence on 20th-century fiction.'),
(6, 'F. Scott', 'Fitzgerald', 'An American novelist and short-story writer, whose works illustrate the Jazz Age. Considered one of the greatest American writers of the 20th century.'),
(7, 'Herman', 'Melville', 'An American novelist, short story writer, essayist, and poet of the American Renaissance period. His writing draws on his experience at sea as a common sailor.'),
(8, 'Charles', 'Dickens', 'An English writer and social critic who created some of the world\'s best-known fictional characters and is regarded by many as the greatest novelist of the Victorian era.'),
(9, 'J.R.R.', 'Tolkien', 'An English writer, poet, philologist, and academic, best known as the author of the high fantasy works The Hobbit and The Lord of the Rings.'),
(10, 'Virginia', 'Woolf', 'An English writer, considered one of the foremost modernists of the twentieth century and a pioneer in the use of stream of consciousness as a narrative device.'),
(11, 'Mark', 'Twain', 'An American writer, humorist, entrepreneur, publisher, and lecturer. He was praised as the "greatest humorist the United States has produced."'),
(12, 'Charlotte', 'Brontë', 'An English novelist and poet, the third of the Brontë sisters. She wrote under the pen name Currer Bell.'),
(13, 'Emily', 'Brontë', 'An English novelist and poet who is best known for her only novel, Wuthering Heights, now considered a classic of English literature.'),
(14, 'Oscar', 'Wilde', 'An Irish poet and playwright. After writing in different forms throughout the 1880s, he became one of London\'s most popular playwrights in the early 1890s.'),
(15, 'Arthur Conan', 'Doyle', 'A British writer and physician, most noted for his fictional stories about the detective Sherlock Holmes, which are generally considered milestones in the field of crime fiction.'),
(16, 'Edgar Allan', 'Poe', 'An American writer, poet, editor, and literary critic. Poe is best known for his poetry and short stories, particularly his tales of mystery and the macabre.'),
(17, 'Nathaniel', 'Hawthorne', 'An American novelist, dark romantic, and short story writer. His themes often center on the inherent evil and sin of humanity.'),
(18, 'Thomas', 'Hardy', 'An English novelist and poet. A Victorian realist in the tradition of George Eliot, he was influenced both in his novels and in his poetry by Romanticism.'),
(19, 'H.G.', 'Wells', 'An English writer. Prolific in many genres, he wrote dozens of novels, short stories, and works of social commentary, satire, biography, and autobiography.'),
(20, 'Rudyard', 'Kipling', 'An English journalist, short-story writer, poet, and novelist. He was born in India, which inspired much of his work.'),
(21, 'Robert Louis', 'Stevenson', 'A Scottish novelist, poet, essayist, and travel writer. He is best known for works such as Treasure Island, Kidnapped, Strange Case of Dr Jekyll and Mr Hyde.'),
(22, 'Bram', 'Stoker', 'An Irish novelist and short story writer, best known today for his 1897 Gothic horror novel Dracula.'),
(23, 'Joseph', 'Conrad', 'A Polish-British novelist regarded as one of the great writers in the English language. He wrote stories and novels, mostly with a nautical or seaborne setting.'),
(24, 'Aldous', 'Huxley', 'An English writer and philosopher. He wrote nearly fifty novels, both fiction and non-fiction, as well as wide-ranging essays, narratives, and poems.'),
(25, 'T.S.', 'Eliot', 'An essayist, publisher, playwright, literary and social critic, and "one of the twentieth century\'s major poets."'),
(26, 'Gabriel García', 'Márquez', 'A Colombian novelist, short-story writer, screenwriter and journalist, known affectionately as Gabo or Gabito. He was awarded the 1982 Nobel Prize in Literature.'),
(27, 'H.P.', 'Lovecraft', 'An American writer known for his horror fiction, particularly the Cthulhu Mythos, influential in the cosmic horror genre.'),
(28, 'Salman', 'Rushdie', 'A British Indian novelist and essayist. His work, combining magical realism with historical fiction, is primarily concerned with the many connections, disruptions, and migrations between Eastern and Western civilizations.'),
(29, 'Margaret', 'Atwood', 'A Canadian poet, novelist, literary critic, essayist, inventor, teacher, and environmental activist. She is a winner of numerous literary awards.'),
(30, 'Toni', 'Morrison', 'An American novelist, essayist, book editor, and college professor. Her novels are known for their epic themes, exquisite language, and richly drawn African American characters.'),
(31, 'Chinua', 'Achebe', 'A Nigerian novelist, poet, professor, and critic. His first novel Things Fall Apart (1958) is the most widely read book in modern African literature.'),
(32, 'Kazuo', 'Ishiguro', 'A British novelist, screenwriter, and short-story writer. He was awarded the Nobel Prize in Literature in 2017.'),
(33, 'Chimamanda Ngozi', 'Adichie', 'A Nigerian writer whose works range from novels to short stories to non-fiction. She has been described in The Times Literary Supplement as "the most important of a generation of Anglophone writers".'),
(34, 'Stephen', 'King', 'An American author of horror, supernatural fiction, suspense, crime, science-fiction, and fantasy novels. His books have sold more than 350 million copies.'),
(35, 'J.K.', 'Rowling', 'A British novelist and screenwriter who wrote the Harry Potter fantasy series.'),
(36, 'Dan', 'Brown', 'An American author of thriller fiction, best known for the Robert Langdon series including The Da Vinci Code.'),
(37, 'Neil', 'Gaiman', 'An English author of short fiction, novels, comic books, graphic novels, audio theatre, and films.'),
(38, 'Terry', 'Pratchett', 'An English humorist, satirist, and author of fantasy novels, especially Discworld.'),
(39, 'Philip K.', 'Dick', 'An American science fiction writer. He wrote 44 published novels and approximately 121 short stories, most of which appeared in science fiction magazines.'),
(40, 'Isaac', 'Asimov', 'An American writer and professor of biochemistry at Boston University. He was one of the most prolific writers of all time, having written or edited more than 500 books.'),
(41, 'Arthur C.', 'Clarke', 'An English science fiction writer, science writer and futurist, inventor, undersea explorer, and television series host.'),
(42, 'Frank', 'Herbert', 'An American science fiction author best known for the novel Dune and its five sequels.'),
(43, 'Ray', 'Bradbury', 'An American author and screenwriter. One of the most celebrated 20th-century American writers, he wrote fantasy, science fiction, horror, and mystery genres.'),
(44, 'Ursula K.', 'Le Guin', 'An American author known for her works of speculative fiction, including science fiction and fantasy, often exploring utopian and dystopian societies.'),
(45, 'Margaret', 'Mitchell', 'An American novelist. She wrote only one novel, Gone With the Wind, a historical romance set in Georgia during the American Civil War.'),
(46, 'Harper', 'Lee', 'An American novelist widely known for her 1960 novel To Kill a Mockingbird, which won the Pulitzer Prize for Fiction.'),
(47, 'Sylvia', 'Plath', 'An American poet, novelist, and short-story writer. She is credited with advancing the genre of confessional poetry.'),
(48, 'Langston', 'Hughes', 'An American poet, social activist, novelist, playwright, and columnist from Joplin, Missouri. One of the earliest innovators of the then-new literary art form jazz poetry.'),
(49, 'Maya', 'Angelou', 'An American poet, memoirist, and civil rights activist. She published seven autobiographies, three books of essays, several books of poetry, and is credited with a list of plays, movies, and television shows spanning over 50 years.'),
(50, 'Ralph', 'Ellison', 'An American novelist, literary critic, and scholar best known for his novel Invisible Man, which won the National Book Award for 1953.'),
(51, 'James', 'Baldwin', 'An American novelist, playwright, essayist, poet, and activist. His essays explore intricacies of racial, sexual, and class distinctions in Western societies, most notably in mid-20th-century America.'),
(52, 'Alice', 'Walker', 'An American novelist, short story writer, poet, and activist. She wrote the critically acclaimed novel The Color Purple for which she won the National Book Award for Fiction and the Pulitzer Prize for Fiction.'),
(53, 'Gustave', 'Flaubert', 'A French novelist known for his meticulous style and the novel Madame Bovary, a landmark work of literary realism.'),
(54, 'Victor', 'Hugo', 'A French poet, novelist, and dramatist of the Romantic movement, best known for Les Misérables and The Hunchback of Notre-Dame.'),
(55, 'Miguel de', 'Cervantes', 'A Spanish writer widely regarded as the greatest writer in the Spanish language, best known for his novel Don Quixote, considered the first modern novel.'),
(56, 'Gabriel', 'Mistral', 'A Chilean poet, educator, and diplomat, the first Latin American woman to win the Nobel Prize in Literature in 1945 for her lyric poetry.'),
(57, 'Pablo', 'Neruda', 'A Chilean poet and diplomat, awarded the Nobel Prize in Literature in 1971, known for his passionate and politically charged poetry.'),
(58, 'Isabel', 'Allende', 'A Chilean-American novelist known for works like The House of the Spirits, blending magical realism with historical and political themes.'),
(59, 'Haruki', 'Murakami', 'A Japanese writer known for his surreal, melancholic novels like Norwegian Wood and Kafka on the Shore, blending magical realism with modern existential themes.'),
(60, 'Zora Neale', 'Hurston', 'An American author and anthropologist, best known for her novel Their Eyes Were Watching God, a key work of the Harlem Renaissance.'),
(61, 'D.H.', 'Lawrence', 'An English novelist, poet, and essayist whose works, such as Lady Chatterley’s Lover, explore human relationships, sexuality, and industrialization.'),
(62, 'John', 'Steinbeck', 'An American author known for novels like The Grapes of Wrath and Of Mice and Men, which address social issues and the human condition.'),
(63, 'William', 'Faulkner', 'An American novelist known for his complex narratives and stream-of-consciousness style in works like The Sound and the Fury, set in the American South.'),
(64, 'Edith', 'Wharton', 'An American novelist and short-story writer, the first woman to win the Pulitzer Prize for Fiction for The Age of Innocence, exploring themes of class and society.'),
(65, 'Franz', 'Kafka', 'A Czech novelist and short-story writer whose works, like The Metamorphosis and The Trial, are known for their existential and absurdist themes.'),
(66, 'James', 'Joyce', 'An Irish novelist and poet, a key figure in modernist literature, best known for Ulysses and A Portrait of the Artist as a Young Man.'),
(67, 'Marcel', 'Proust', 'A French novelist known for his monumental work In Search of Lost Time, a landmark in modernist literature exploring memory and identity.'),
(68, 'Albert', 'Camus', 'A French philosopher, author, and journalist, known for existentialist works like The Stranger and The Plague, awarded the Nobel Prize in Literature in 1957.'),
(69, 'Jean-Paul', 'Sartre', 'A French philosopher, novelist, and playwright, a leading figure in existentialism, known for works like Nausea and Being and Nothingness.'),
(70, 'Simone de', 'Beauvoir', 'A French writer, philosopher, and feminist, best known for The Second Sex, a foundational text in feminist theory, and her novels like She Came to Stay.'),
(71, 'George Bernard', 'Shaw', 'An Irish playwright and critic, known for plays like Pygmalion and Saint Joan, awarded the Nobel Prize in Literature in 1925.'),
(72, 'Henrik', 'Ibsen', 'A Norwegian playwright and poet, considered the father of modern drama, known for works like A Doll’s House and Hedda Gabler.'),
(73, 'Edna', 'O''Brien', 'An Irish novelist and short-story writer, known for her works like The Country Girls, exploring Irish society and women’s experiences.'),
(74, 'Rabindranath', 'Tagore', 'An Indian poet, novelist, and playwright, the first non-European to win the Nobel Prize in Literature in 1913 for his collection Gitanjali.'),
(75, 'Luigi', 'Pirandello', 'An Italian playwright, novelist, and short-story writer, awarded the Nobel Prize in Literature in 1934 for works like Six Characters in Search of an Author.'),
(76, 'Jorge Luis', 'Borges', 'An Argentine short-story writer, essayist, and poet, known for his philosophical and fantastical stories like Ficciones and The Aleph.'),
(77, 'Octavio', 'Paz', 'A Mexican poet and diplomat, awarded the Nobel Prize in Literature in 1990 for his works exploring Mexican identity and existential themes.'),
(78, 'Knut', 'Hamsun', 'A Norwegian writer, awarded the Nobel Prize in Literature in 1920, known for his novel Hunger, a precursor to modernist literature.'),
(79, 'Emily', 'Dickinson', 'An American poet known for her innovative and enigmatic poetry, much of which was published posthumously.'),
(80, 'Walt', 'Whitman', 'An American poet, essayist, and journalist, known for his collection Leaves of Grass, a cornerstone of American literature.'),
(81, 'Samuel', 'Beckett', 'An Irish novelist, playwright, and poet, known for his absurdist works like Waiting for Godot, awarded the Nobel Prize in Literature in 1969.'),
(82, 'E.M.', 'Forster', 'An English novelist known for works like A Passage to India and Howards End, exploring themes of class, culture, and human connection.'),
(83, 'Graham', 'Greene', 'An English novelist and journalist, known for his morally complex works like The Power and the Glory and The Quiet American.'),
(84, 'Doris', 'Lessing', 'A British-Zimbabwean novelist, awarded the Nobel Prize in Literature in 2007 for works like The Golden Notebook, exploring feminist and social themes.'),
(85, 'Czesław', 'Miłosz', 'A Polish poet, prose writer, and translator, awarded the Nobel Prize in Literature in 1980 for his works exploring human morality and history.'),
(86, 'Khaled', 'Hosseini', 'An Afghan-American novelist, known for his emotionally resonant novels like The Kite Runner and A Thousand Splendid Suns.'),
(87, 'Jhumpa', 'Lahiri', 'An American author of Indian descent, known for her Pulitzer Prize-winning short-story collection Interpreter of Maladies and novels like The Namesake.'),
(88, 'Orhan', 'Pamuk', 'A Turkish novelist, awarded the Nobel Prize in Literature in 2006, known for works like My Name Is Red and Snow, blending history and culture.'),
(89, 'Nadine', 'Gordimer', 'A South African writer and activist, awarded the Nobel Prize in Literature in 1991 for novels like July’s People, addressing apartheid and social issues.'),
(90, 'Michael', 'Ondaatje', 'A Sri Lankan-Canadian novelist and poet, known for his novel The English Patient, which won the Booker Prize and was adapted into an acclaimed film.'),
(91, 'Yasunari', 'Kawabata', 'A Japanese novelist, the first Japanese author to win the Nobel Prize in Literature in 1968, known for works like Snow Country.'),
(92, 'Banana', 'Yoshimoto', 'A Japanese novelist known for her minimalist and emotionally resonant works like Kitchen and Lizard.'),
(93, 'Amrita', 'Pritam', 'An Indian novelist and poet, known for her poignant works like Pinjar, exploring themes of partition and gender.'),
(94, 'Ngũgĩ wa', 'Thiong’o', 'A Kenyan novelist and playwright, known for works like A Grain of Wheat, advocating for African languages in literature.'),
(95, 'Elie', 'Wiesel', 'A Romanian-born American writer, Holocaust survivor, and Nobel Peace Prize laureate, known for his memoir Night.'),
(96, 'Anita', 'Desai', 'An Indian novelist known for works like Clear Light of Day, exploring family dynamics and post-colonial Indian society.'),
(97, 'V.S.', 'Naipaul', 'A Trinidadian-British writer, awarded the Nobel Prize in Literature in 2001 for works like A House for Mr Biswas, exploring post-colonial themes.'),
(98, 'Alice', 'Munro', 'A Canadian short-story writer, awarded the Nobel Prize in Literature in 2013, known for her masterful short stories like Runaway.'),
(99, 'Naguib', 'Mahfouz', 'An Egyptian novelist, awarded the Nobel Prize in Literature in 1988, known for his Cairo Trilogy, exploring modern Egyptian society.'),
(100, 'Maxine Hong', 'Kingston', 'A Chinese-American author known for her memoir The Woman Warrior, blending autobiography with Chinese folklore.');